const query = $json.query ?? $query ?? {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

const isVerifyRequest = !!(mode && token && challenge);
const isVerifyValid =
  isVerifyRequest &&
  mode === 'subscribe' &&
  token === $env.WHATSAPP_VERIFY_TOKEN;

return [
  {
    json: {
      ...$json,
      verify: {
        is_request: isVerifyRequest,
        is_valid: isVerifyValid,
        challenge: String(challenge ?? ''),
      },
    },
  },
];

const data = $json;
const headers = $headers ?? data.headers ?? {};
const query = data.query ?? {};
const payload = data.body ?? data;
const secret = headers['x-origin-secret'] || headers['X-Origin-Secret'] || query.secret;
const validSecret = secret === $env.ORIGIN_SECRET;

const entry = payload.entry?.[0] ?? {};
const change = entry.changes?.[0] ?? {};
const value = change.value ?? {};
const message = value.messages?.[0] ?? {};

const from = message.from ?? '';
const messageId = message.id ?? '';
const timestamp = message.timestamp ? new Date(parseInt(message.timestamp, 10) * 1000).toISOString() : new Date().toISOString();
const type = message.type || 'text';

let text = '';
let mediaId = '';
let mediaMime = '';

if (type === 'text') {
  text = message.text?.body || '';
} else if (type === 'image') {
  mediaId = message.image?.id || '';
  mediaMime = message.image?.mime_type || '';
  text = message.image?.caption || '';
} else if (type === 'document') {
  mediaId = message.document?.id || '';
  mediaMime = message.document?.mime_type || '';
  text = message.document?.caption || '';
}

const normalizePhone = (raw) => {
  const digits = (raw || '').replace(/[^0-9]/g, '');
  return digits ? `+${digits}` : '';
};

return [{
  json: {
    valid_secret: !!validSecret,
    timestamp,
    whatsapp: normalizePhone(from),
    message_id: messageId,
    message_type: mediaId ? 'media' : 'text',
    text: text || '',
    media_id: mediaId || '',
    media_mime: mediaMime || ''
  }
}];

const WINDOW_SEC = Number($env.WINDOW_SEC || 12);
const now = Date.now();
const rows = items.map(i => i.json);
const pending = rows.filter(r => r.status === 'PENDING');

const byWhatsapp = {};
for (const row of pending) {
  const wa = row.whatsapp || '';
  if (!wa) continue;
  if (!byWhatsapp[wa]) byWhatsapp[wa] = [];
  byWhatsapp[wa].push(row);
}

const output = [];
for (const [wa, msgs] of Object.entries(byWhatsapp)) {
  const sorted = msgs.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  const last = sorted[sorted.length - 1];
  const ageSec = (now - new Date(last.timestamp).getTime()) / 1000;
  if (ageSec < WINDOW_SEC) continue;

  const combinedText = sorted.map(m => m.text).filter(Boolean).join('
');
  const hasImage = sorted.some(m => (m.media_mime || '').startsWith('image/'));
  const mediaIds = sorted.filter(m => (m.media_mime || '').startsWith('image/')).map(m => m.media_id).filter(Boolean);
  const pendingTimestamps = sorted.map(m => m.timestamp);
  const pendingMessageIds = sorted.map(m => m.message_id).filter(Boolean);

  output.push({
    json: {
      whatsapp: wa,
      combined_text: combinedText,
      has_image: hasImage,
      media_ids: mediaIds,
      pending_timestamps: pendingTimestamps,
      pending_message_ids: pendingMessageIds,
      last_message_at: last.timestamp,
      batch_id: `batch_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`
    }
  });
}

return output;

const text = ($json.combined_text || '').trim();
const upper = text.toUpperCase();
let action = 'UNKNOWN';
let args = [];

const parts = text.split(/[ ]+/);

if (upper.startsWith('BUSCAR CLIENTE')) {
  action = 'BUSCAR_CLIENTE';
  args = [text.replace(/BUSCAR CLIENTE[ ]*/i, '')];
} else if (upper.startsWith('CONFIRMAR PAGO')) {
  action = 'CONFIRMAR_PAGO';
  args = [text.replace(/CONFIRMAR PAGO[ ]*/i, '')];
} else if (upper.startsWith('RECHAZAR PAGO')) {
  action = 'RECHAZAR_PAGO';
  args = [text.replace(/RECHAZAR PAGO[ ]*/i, '')];
} else if (upper.startsWith('ACTUALIZAR LINK')) {
  action = 'ACTUALIZAR_LINK';
  args = parts.slice(2);
} else if (upper.startsWith('SUSPENDER')) {
  action = 'SUSPENDER';
  args = [parts[1]];
} else if (upper.startsWith('ACTIVAR')) {
  action = 'ACTIVAR';
  args = [parts[1]];
} else if (upper.startsWith('SET VENCIMIENTO')) {
  action = 'SET_VENCIMIENTO';
  args = parts.slice(2);
} else if (upper.startsWith('SET MONTO')) {
  action = 'SET_MONTO';
  args = parts.slice(2);
}

return [{ json: { ...$json, action, args } }];

const clientes = $items('Read clientes (admin)').map(i => i.json);
const pagos = $items('Read pagos (admin)').map(i => i.json);
const { action, args } = $json;
let response = 'Comando no reconocido.';
let update = null;

const findClienteById = (id) => clientes.find(c => c.cliente_id === id);
const findPagoById = (id) => pagos.find(p => p.pago_id === id);

if (action === 'BUSCAR_CLIENTE') {
  const q = (args[0] || '').toLowerCase();
  const matches = clientes.filter(c => (c.nombre || '').toLowerCase().includes(q) || (c.whatsapp || '').includes(q));
  response = matches.length ? matches.map(c => `${c.cliente_id} | ${c.nombre} | ${c.whatsapp} | ${c.estado}`).join('
') : 'Sin resultados.';
}

if (action === 'CONFIRMAR_PAGO') {
  const pago = findPagoById(args[0]);
  if (pago) {
    update = { sheet: 'pagos', key: 'pago_id', value: pago.pago_id, data: { estado_pago: 'CONFIRMADO', validado_por: 'OWNER' } };
    response = `Pago ${pago.pago_id} confirmado.`;
  } else {
    response = 'Pago no encontrado.';
  }
}

if (action === 'RECHAZAR_PAGO') {
  const pago = findPagoById(args[0]);
  if (pago) {
    update = { sheet: 'pagos', key: 'pago_id', value: pago.pago_id, data: { estado_pago: 'RECHAZADO', validado_por: 'OWNER' } };
    response = `Pago ${pago.pago_id} rechazado.`;
  } else {
    response = 'Pago no encontrado.';
  }
}

if (action === 'ACTUALIZAR_LINK') {
  const [clienteId, url] = args;
  const cliente = findClienteById(clienteId);
  if (cliente && url) {
    update = { sheet: 'clientes', key: 'cliente_id', value: clienteId, data: { link_pago: url } };
    response = `Link actualizado para ${clienteId}.`;
  } else {
    response = 'Cliente o URL inválido.';
  }
}

if (action === 'SUSPENDER') {
  const clienteId = args[0];
  const cliente = findClienteById(clienteId);
  if (cliente) {
    update = { sheet: 'clientes', key: 'cliente_id', value: clienteId, data: { estado: 'SUSPENDIDO' } };
    response = `Cliente ${clienteId} suspendido.`;
  } else {
    response = 'Cliente no encontrado.';
  }
}

if (action === 'ACTIVAR') {
  const clienteId = args[0];
  const cliente = findClienteById(clienteId);
  if (cliente) {
    update = { sheet: 'clientes', key: 'cliente_id', value: clienteId, data: { estado: 'ACTIVO' } };
    response = `Cliente ${clienteId} activado.`;
  } else {
    response = 'Cliente no encontrado.';
  }
}

if (action === 'SET_VENCIMIENTO') {
  const [clienteId, fecha] = args;
  const cliente = findClienteById(clienteId);
  if (cliente && fecha) {
    update = { sheet: 'clientes', key: 'cliente_id', value: clienteId, data: { proximo_vencimiento: fecha } };
    response = `Vencimiento actualizado para ${clienteId}.`;
  } else {
    response = 'Datos inválidos.';
  }
}

if (action === 'SET_MONTO') {
  const [clienteId, monto] = args;
  const cliente = findClienteById(clienteId);
  if (cliente && monto) {
    update = { sheet: 'clientes', key: 'cliente_id', value: clienteId, data: { monto_mensual: monto } };
    response = `Monto actualizado para ${clienteId}.`;
  } else {
    response = 'Datos inválidos.';
  }
}

return [{ json: { ...$json, response, update } }];

const u = $json.update || {};
const data = (u.data || {});
const key = u.key || '';
const value = u.value || '';
return [{ json: { ...data, [key]: value } }];

const resumen = ($json.response || '').slice(0, 120);
return [{
  json: {
    timestamp: new Date().toISOString(),
    whatsapp: $json.whatsapp || '',
    mensaje_usuario: resumen,
    tipo_mensaje: 'ADMIN',
    media_url: '',
    procesado: 'SI'
  }
}];

const clientes = items.map(i => i.json);
const batch = ($items('Agrupar y debounce')[0] || {}).json || {};
const wa = batch.whatsapp || '';
const cliente = clientes.find(c => c.whatsapp === wa) || null;
return [{ json: { ...batch, cliente } }];

return [{
  json: {
    timestamp: new Date().toISOString(),
    whatsapp: $json.whatsapp || '',
    mensaje_usuario: 'Solicitud de alta enviada',
    tipo_mensaje: 'NUEVO_CLIENTE',
    media_url: '',
    procesado: 'SI'
  }
}];

const cliente = $json.cliente;
const logs = $items('Read mensajes_log').map(i => i.json).filter(l => l.whatsapp === $json.whatsapp);
const lastLogs = logs.slice(-10);
const systemPrompt = 'Eres asistente de cobros y atención. Responde corto, claro, cordial. No inventes pagos. Si falta info, pregunta. No cambies de tema. Mantente en contexto del negocio. Si el usuario envía varios mensajes unidos, respóndelos juntos.';
const context = { cliente: cliente || {}, ultimos_mensajes: lastLogs };
return [{ json: { ...$json, system_prompt: systemPrompt, context_json: JSON.stringify(context), user_input: $json.combined_text || '' } }];

const fallback = 'Gracias por tu mensaje. ¿Podrías darme más detalles?';
const error = $json.error || ($json.response && $json.response.error) || null;
const outputText = ($json.output_text || '').trim();
const outputs = Array.isArray($json.output) ? $json.output : [];
const contentText = outputs
  .flatMap(o => Array.isArray(o.content) ? o.content : [])
  .map(c => (c.text || c.output_text || '').trim())
  .filter(Boolean)
  .join('
');
const reply = (outputText || contentText || fallback).trim();
const openaiFailed = !!error || (!outputText && !contentText);
const errorMessage = error ? (error.message || JSON.stringify(error)) : (openaiFailed ? 'OpenAI response missing output_text/output.' : '');
return [{ json: { ...$json, ai_reply: reply, openai_failed: openaiFailed, openai_error: errorMessage } }];

const bin = $binary.data;
if (!bin) return [{ json: { ...$json, image_data_url: '' } }];
const mime = bin.mimeType || 'image/jpeg';
const dataUrl = `data:${mime};base64,${bin.data}`;
return [{ json: { ...$json, image_data_url: dataUrl } }];

const cliente = $json.cliente;
let parsed = null;
try {
  const outputText = ($json.output_text || '').trim();
  const outputs = Array.isArray($json.output) ? $json.output : [];
  const contentText = outputs
    .flatMap(o => Array.isArray(o.content) ? o.content : [])
    .map(c => (c.text || c.output_text || '').trim())
    .filter(Boolean)
    .join('');
  const raw = outputText || contentText || '';
  parsed = raw ? JSON.parse(raw) : null;
} catch (e) {
  parsed = null;
}
const monto = Number(parsed && parsed.monto ? parsed.monto : 0);
const esperado = Number(cliente && cliente.monto_mensual ? cliente.monto_mensual : 0);
const diffOk = esperado ? (Math.abs(monto - esperado) / esperado) <= 0.05 : true;
const conf = Number(parsed && parsed.confidence_0_100 ? parsed.confidence_0_100 : 0);
const ok = parsed && conf >= 80 && diffOk;
return [{ json: { ...$json, vision_data: parsed, vision_ok: !!ok } }];

const v = $json.vision_data || {};
const pagoId = `pago_${Date.now()}_${Math.random().toString(36).slice(2,6)}`;
return [{
  json: {
    pago_id: pagoId,
    cliente_id: $json.cliente && $json.cliente.cliente_id ? $json.cliente.cliente_id : '',
    whatsapp: $json.whatsapp || ($json.cliente && $json.cliente.whatsapp ? $json.cliente.whatsapp : ''),
    monto: v.monto || '',
    metodo_pago: v.entidad || '',
    fecha_pago: v.fecha || '',
    estado_pago: 'PENDIENTE_CONFIRMACION'
  }
}];

return [{
  json: {
    cliente_id: $json.cliente?.cliente_id || '',
    ultimo_contacto: new Date().toISOString()
  }
}];

const clientes = $items('Read clientes (recordatorios)').map(i => i.json);
const logs = $items('Read logs (recordatorios)').map(i => i.json);
const now = new Date();

const types = [
  { name: 'RECORDATORIO_7D', diff: 7 },
  { name: 'RECORDATORIO_2D', diff: 2 },
  { name: 'VENCE_HOY', diff: 0 },
  { name: 'SEGUIMIENTO_3D', diff: -3 },
  { name: 'SEGUIMIENTO_7D', diff: -7 },
  { name: 'MOROSO_14D', diff: -14 }
];

const out = [];
for (const c of clientes) {
  if (c.estado !== 'ACTIVO' || c.consentimiento_mensajes !== 'SI') continue;
  const venc = c.proximo_vencimiento ? new Date(c.proximo_vencimiento) : null;
  if (!venc) continue;
  const diffDays = Math.floor((venc - now) / (1000 * 60 * 60 * 24));
  const match = types.find(t => diffDays === t.diff);
  if (!match) continue;

  const recordatorioId = `${c.cliente_id}_${match.name}_${c.proximo_vencimiento}`;
  const already = logs.find(l => l.recordatorio_id === recordatorioId);
  if (already) continue;

  out.push({
    json: {
      cliente: c,
      tipo_mensaje: match.name,
      recordatorio_id: recordatorioId,
      texto: `Hola ${c.nombre}, recordatorio: tu pago vence el ${c.proximo_vencimiento}. Si ya pagaste, ignora este mensaje.`
    }
  });
}

return out;

return [{
  json: {
    recordatorio_id: $json.recordatorio_id || '',
    cliente_id: $json.cliente && $json.cliente.cliente_id ? $json.cliente.cliente_id : '',
    whatsapp: $json.cliente && $json.cliente.whatsapp ? $json.cliente.whatsapp : '',
    mensaje: $json.texto || '',
    fecha_envio: new Date().toISOString(),
    enviado: 'SI'
  }
}];

const clientes = items.map(i => i.json).filter(c => c.estado === 'ACTIVO');
const now = new Date();
let porVencer = 0;
let venceHoy = 0;
let vencidos1a7 = 0;
let morosos = 0;
let montoEsperado = 0;

for (const c of clientes) {
  const venc = c.proximo_vencimiento ? new Date(c.proximo_vencimiento) : null;
  if (!venc) continue;
  const diff = Math.floor((venc - now) / (1000 * 60 * 60 * 24));
  if (diff >= 0 && diff <= 2) porVencer += 1;
  if (diff === 0) venceHoy += 1;
  if (diff < 0 && diff >= -7) vencidos1a7 += 1;
  if (diff <= -8) morosos += 1;
  montoEsperado += Number(c.monto_mensual || 0);
}

const texto = `Reporte: Activos ${clientes.length}. Por vencer (0-2): ${porVencer}. Vence hoy: ${venceHoy}. Vencidos 1-7: ${vencidos1a7}. Morosos 8+: ${morosos}. Monto esperado: ${montoEsperado}.`;
return [{
  json: {
    texto,
    fecha: now.toISOString().slice(0, 10),
    total_clientes: clientes.length,
    total_pagos: 0,
    monto_total: montoEsperado,
    mensajes_recibidos: 0,
    observaciones: texto
  }
}];

return [{
  json: {
    fecha: $json.fecha || new Date().toISOString().slice(0, 10),
    total_clientes: $json.total_clientes || 0,
    total_pagos: $json.total_pagos || 0,
    monto_total: $json.monto_total || 0,
    mensajes_recibidos: $json.mensajes_recibidos || 0,
    observaciones: $json.observaciones || $json.texto || ''
  }
}];

const messageIds = Array.isArray($json.pending_message_ids) ? [...$json.pending_message_ids] : [];
if (!messageIds.length && $json.pending_message_ids) {
  messageIds.push($json.pending_message_ids);
}

return messageIds.map(messageId => ({ json: { message_id: messageId, status: 'DONE', batch_id: $json.batch_id || '' } }));

const messageIds = Array.isArray($json.pending_message_ids) ? [...$json.pending_message_ids] : [];
if (!messageIds.length && $json.pending_message_ids) {
  messageIds.push($json.pending_message_ids);
}

return messageIds.map(messageId => ({ json: { message_id: messageId, status: 'DONE', batch_id: $json.batch_id || '' } }));

const messageIds = Array.isArray($json.pending_message_ids) ? [...$json.pending_message_ids] : [];
if (!messageIds.length && $json.pending_message_ids) {
  messageIds.push($json.pending_message_ids);
}

return messageIds.map(messageId => ({ json: { message_id: messageId, status: 'DONE', batch_id: $json.batch_id || '' } }));

return [{
  json: {
    timestamp: new Date().toISOString(),
    whatsapp: $json.whatsapp || '',
    mensaje_usuario: $json.user_input || $json.combined_text || '',
    respuesta_ia: $json.ai_reply || '',
    contexto: $json.context_json || ''
  }
}];
